    @_mutmut_mutated(mutants_xǁCodeGeneratorǁ_try_patch_tool__mutmut)
    def _try_patch_tool(self, file_path: str, old_content: str, new_content: str) -> None:
        """patch 명령어로 패치 적용"""
        import difflib

        # diff 생성
        diff = list(
            difflib.unified_diff(
                old_content.splitlines(keepends=True),
                new_content.splitlines(keepends=True),
                fromfile=f"a/{file_path}",
                tofile=f"b/{file_path}",
            )
        )

        if diff:
            # 임시 파일에 패치 저장
            with tempfile.NamedTemporaryFile(mode="w", suffix=".patch", delete=False) as f:
                f.writelines(diff)
                patch_file = f.name

            try:
                # patch 적용
                result = subprocess.run(
                    ["patch", "-p1", "-i", patch_file],
                    cwd=self.workspace,
                    capture_output=True,
                    text=True,
                    timeout=30,
                )
                if result.returncode != 0:
                    # 패치 실패 시 전체 교체
                    (self.workspace / file_path).write_text(new_content, encoding="utf-8")
            except Exception:
                # 실패 시 전체 교체
                (self.workspace / file_path).write_text(new_content, encoding="utf-8")
            finally:
                Path(patch_file).unlink(missing_ok=True)
        else:
            # 변경사항 없음
            pass

